if(!exists('simulate_operating_cashflows'))library(creditratingsystem)
so_contract<-list(contract_id='operations',version='1',currency='EUR',period_unit='year',quantity_unit='units',initial_working_capital=10,include_asset_disposals_in_cfads=FALSE)
r<-list(scenario_id='s',period_start='2021-01-01',period_end='2022-01-01',currency='EUR',base_quantity=10,base_unit_price=20,base_unit_variable_cost=6,base_fixed_cost=20,volume_multiplier=1,price_multiplier=1,variable_cost_multiplier=1,fixed_cost_multiplier=1,working_capital_revenue_ratio=.1,cash_taxes=10,capex=15,asset_disposals=7,other_operating_cash=0)
r2<-r;r2$period_start<-'2022-01-01';r2$period_end<-'2023-01-01';r2$volume_multiplier<-.5;r2$cash_taxes<-5;r2$capex<-0;so_rows<-list(r,r2)
sv<-function(x,key)vapply(x,function(r)r[[key]],numeric(1))
r<-simulate_operating_cashflows(so_rows,so_contract)$value$periods;stopifnot(identical(sv(r,'cfads'),c(85,55)),identical(sv(r,'change_working_capital'),c(10,-10)),r[[1]]$revenue==200,r[[1]]$variable_cost==60,r[[1]]$ebitda==120)
p<-so_contract;p$include_asset_disposals_in_cfads<-TRUE;stopifnot(identical(sv(simulate_operating_cashflows(so_rows,p)$value$periods,'cfads'),c(92,62)),identical(simulate_operating_cashflows(rev(so_rows),p)$value,simulate_operating_cashflows(so_rows,p)$value))
sa_params<-list(asset_id='a',currency='EUR',valuation_date='2021-01-01',initial_value=100,salvage_value=20,initial_age_years=2,economic_life_years=10,depreciation_model='straight_line',idiosyncratic_volatility=0,probability_measure='PHYSICAL',year_basis_days=365)
sa_rows<-list(list(scenario_id='s',date='2022-01-01',market_index=1.2,innovation=1),list(scenario_id='s',date='2023-01-01',market_index=1,innovation=-1))
r<-simulate_asset_values(sa_params,sa_rows)$value$paths;stopifnot(identical(sv(r,'ageing_baseline'),c(90,80)),identical(sv(r,'asset_value'),c(108,80)))
p<-sa_params;p$idiosyncratic_volatility<-.2;r<-simulate_asset_values(p,sa_rows)$value$paths;stopifnot(max(abs(sv(r,'asset_value')-c(108*exp(.18),80*exp(-.04))))<1e-12)
for(row in r)stopifnot(abs(100+row$ageing_contribution+row$market_contribution+row$idiosyncratic_contribution-row$asset_value)<1e-12)
stopifnot(identical(simulate_asset_values(sa_params,rev(sa_rows))$value,simulate_asset_values(sa_params,sa_rows)$value))
p<-sa_params;p$depreciation_model<-'geometric_to_salvage';p$annual_depreciation_rate<-log(2);stopifnot(max(abs(sv(simulate_asset_values(p,sa_rows)$value$paths,'ageing_baseline')-c(60,40)))<1e-12)
se<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
p<-sa_params;p$probability_measure<-'Q';se('SIMULATION_ASSET',simulate_asset_values(p,sa_rows));se('SIMULATION_CALENDAR',simulate_asset_values(sa_params,c(sa_rows,sa_rows)))
rows<-so_rows;rows[[2]]$period_start<-'2022-02-01';se('SIMULATION_CALENDAR',simulate_operating_cashflows(rows,so_contract))
cat('Native operating cashflow and physical asset oracles PASS\n')

ctx<-build_calculation_context(currency='EUR',probability_measure='PHYSICAL')
stopifnot(simulate_asset_values(sa_params,sa_rows,context=ctx)$value$paths[[1]]$probability_measure=='PHYSICAL')
ctx<-build_calculation_context(currency='EUR',probability_measure='RISK_NEUTRAL');se('TARGET_MISMATCH',simulate_asset_values(sa_params,sa_rows,context=ctx))
